#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# ──────────────────────────────────────────────────────────────────────────

# Disable inherited tracing before any credential is read or captured.
set +x
set +v
umask 077
export LC_ALL=C
TOTAL_STAGES=5

fail() { printf 'R2 setup stopped: %s\n' "$1" >&2; exit 1; }
[[ -t 0 && -t 1 ]] || fail 'Run in an interactive terminal; do not pipe or record this session.'
SCRIPT_DIR=$(cd -- "$(dirname -- "${BASH_SOURCE[0]}")" && pwd -P)
REPO_ROOT=$(cd -- "$SCRIPT_DIR/.." && pwd -P)
# Never honor inherited ENV_FILE or TMPDIR: secrets have one ignored destination.
ENV_FILE="$REPO_ROOT/.artifacts/r2-setup/credentials.env"
OUTPUT_DIR="${ENV_FILE%/*}"
export TMPDIR="$OUTPUT_DIR"

# Check every ancestor, including ancestors outside the repository. On Windows,
# Bash -L alone misses junctions; PowerShell also checks all ReparsePoint flags.
assert_safe_path() {
  local path="$ENV_FILE"
  while :; do
    [[ ! -L "$path" ]] || fail 'Output path or an ancestor is a symlink.'
    [[ "$path" == / ]] && break
    path=$(dirname -- "$path")
  done
  if [[ "$OSTYPE" == msys* || "$OSTYPE" == cygwin* ]]; then
    command -v powershell.exe >/dev/null || fail 'Windows PowerShell is required to check NTFS safety.'
    R2_SETUP_PATH=$(cygpath -w "$ENV_FILE")
    export R2_SETUP_PATH
    if ! powershell.exe -NoProfile -NonInteractive -Command - >/dev/null 2>&1 <<'PS'
$ErrorActionPreference = 'Stop'
try {
    $path = [IO.Path]::GetFullPath($env:R2_SETUP_PATH)
    while ($path) {
        if (Test-Path -LiteralPath $path) {
            $item = Get-Item -LiteralPath $path -Force
            if ($item.Attributes -band [IO.FileAttributes]::ReparsePoint) { throw 'Unsafe path' }
        }
        $parent = [IO.Directory]::GetParent($path)
        if ($null -eq $parent) { break }
        $path = $parent.FullName
    }
    exit 0
} catch { exit 1 }
PS
    then
      fail 'Output path has a reparse point or could not be verified.'
    fi
  fi
}

# Restrict the dedicated directory on NTFS, with inheritance to temporary files.
# chmod alone is not a confidentiality boundary in Git Bash on Windows.
protect_output() {
  if [[ "$OSTYPE" == msys* || "$OSTYPE" == cygwin* ]]; then
    R2_SETUP_DIR=$(cygpath -w "$OUTPUT_DIR")
    export R2_SETUP_DIR
    if ! powershell.exe -NoProfile -NonInteractive -Command - >/dev/null 2>&1 <<'PS'
$ErrorActionPreference = 'Stop'
try {
    $sid = [Security.Principal.WindowsIdentity]::GetCurrent().User
    $dir = $env:R2_SETUP_DIR
    $paths = @($dir)
    if ($env:R2_SETUP_VALIDATED_FILE -eq 'yes') { $paths += Join-Path $dir 'credentials.env' }
    foreach ($path in $paths) {
        if (!(Test-Path -LiteralPath $path)) { continue }
        $item = Get-Item -LiteralPath $path -Force
        if ($item.Attributes -band [IO.FileAttributes]::ReparsePoint) { throw 'Unsafe path' }
        if ($item.PSIsContainer) {
            $acl = New-Object Security.AccessControl.DirectorySecurity
            $rule = New-Object Security.AccessControl.FileSystemAccessRule($sid, 'FullControl', 'ContainerInherit,ObjectInherit', 'None', 'Allow')
        } else {
            $acl = New-Object Security.AccessControl.FileSecurity
            $rule = New-Object Security.AccessControl.FileSystemAccessRule($sid, 'FullControl', 'Allow')
        }
        $acl.SetOwner($sid)
        $acl.SetAccessRuleProtection($true, $false)
        $acl.AddAccessRule($rule)
        Set-Acl -LiteralPath $path -AclObject $acl
        $verified = Get-Acl -LiteralPath $path
        if (!$verified.AreAccessRulesProtected -or $verified.GetOwner([Security.Principal.SecurityIdentifier]).Value -ne $sid.Value) { throw 'Unverified ACL' }
        $rules = $verified.GetAccessRules($true, $true, [Security.Principal.SecurityIdentifier])
        if ($rules.Count -ne 1 -or $rules[0].IdentityReference.Value -ne $sid.Value -or $rules[0].AccessControlType -ne 'Allow' -or $rules[0].FileSystemRights -ne 'FullControl') { throw 'Unverified ACL' }
    }
    exit 0
} catch { exit 1 }
PS
    then
      fail 'Cannot enforce owner-only NTFS ACLs. Use a private local NTFS checkout; credentials are not accepted until this passes.'
    fi
  else
    [[ -O "$OUTPUT_DIR" && ! -L "$OUTPUT_DIR" ]] || fail 'Output directory must belong to this user.'
    chmod 700 "$OUTPUT_DIR" || fail 'Cannot restrict output directory.'
    if [[ "$R2_SETUP_VALIDATED_FILE" == yes && -f "$ENV_FILE" ]]; then
      [[ -O "$ENV_FILE" ]] || fail 'Credential file must belong to this user.'
      chmod 600 "$ENV_FILE" || fail 'Cannot restrict credential file.'
    fi
  fi
}

validate_value() {
  local key="$1" value="$2"
  case "$key" in
    STAGING_R2_ACCOUNT_ID|PRODUCTION_R2_ACCOUNT_ID) [[ "$value" =~ ^[a-fA-F0-9]{32}$ ]] ;;
    STAGING_R2_BUCKET|PRODUCTION_R2_BUCKET) [[ ${#value} -ge 3 && ${#value} -le 63 && "$value" =~ ^[a-z0-9][a-z0-9-]*[a-z0-9]$ ]] ;;
    STAGING_R2_ACCESS_KEY_ID|PRODUCTION_R2_ACCESS_KEY_ID|STAGING_R2_SECRET_ACCESS_KEY|PRODUCTION_R2_SECRET_ACCESS_KEY)
      # Treat keys as opaque, bounded single-line values; no invented provider format.
      [[ ${#value} -gt 0 && ${#value} -le 4096 && "$value" =~ ^[[:graph:]]+$ ]] ;;
    STAGING_R2_TOKEN_NAME|PRODUCTION_R2_TOKEN_NAME) [[ "$value" =~ ^[a-zA-Z0-9._-]{1,128}$ ]] ;;
    STAGING_R2_TOKEN_TYPE|PRODUCTION_R2_TOKEN_TYPE) [[ "$value" == account || "$value" == user ]] ;;
    STAGING_R2_TOKEN_EXPIRY|PRODUCTION_R2_TOKEN_EXPIRY)
      [[ "$value" == none ]] && return 0
      [[ "$value" =~ ^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}Z$ ]] || return 1
      [[ "$(date -u -d "$value" '+%Y-%m-%dT%H:%M:%SZ' 2>/dev/null)" == "$value" ]] ;;
    *) return 1 ;;
  esac
}

ask_valid() {
  local key="$1" prompt="$2" secret="${3:-no}"
  while :; do
    if [[ "$secret" == yes ]]; then ask_secret "$key" "$prompt"; else ask "$key" "$prompt"; fi
    validate_value "$key" "${!key}" && break
    warn 'Invalid or empty input. Retry; values are never included in errors.'
  done
}
persist() {
  validate_value "$1" "${!1}" || fail 'Refusing to persist an invalid value.'
  assert_safe_path
  write_env "$1" "${!1}"
  protect_output
}

assert_safe_path
[[ ! -e "$OUTPUT_DIR" || -d "$OUTPUT_DIR" ]] || fail 'Output directory is not a directory.'
[[ ! -e "$ENV_FILE" || -f "$ENV_FILE" ]] || fail 'Credential path is not a regular file.'
# Existing file must have this wizard marker and only its known, validated keys.
# Never source this file: credentials may contain shell metacharacters.
mkdir -p -- "$OUTPUT_DIR"
R2_SETUP_VALIDATED_FILE=no
export R2_SETUP_VALIDATED_FILE
protect_output
# Lock before inspecting or creating the file. Never race another wizard run.
mkdir -- "$OUTPUT_DIR/.lock" 2>/dev/null || fail 'Another run is active; if interrupted, inspect then remove the empty .lock directory.'
trap 'rmdir -- "$OUTPUT_DIR/.lock" 2>/dev/null || true' EXIT
if [[ -e "$ENV_FILE" ]]; then
  IFS= read -r header < "$ENV_FILE" || fail 'Existing file is not a wizard output.'
  [[ "$header" == '# FastToWin R2 setup v1' ]] || fail 'Refusing to overwrite an unrelated env file.'
  R2_SETUP_VALIDATED_FILE=yes
  protect_output
  declare -A seen=()
  while IFS= read -r line || [[ -n "$line" ]]; do
    [[ "$line" == '# FastToWin R2 setup v1' ]] && continue
    [[ "$line" == *=* ]] || fail 'Unexpected existing output content.'
    key=${line%%=*}
    validate_value "$key" "${line#*=}" || fail 'Unknown key or invalid existing output.'
    [[ ! ${seen[$key]+present} ]] || fail 'Duplicate key in existing output.'
    seen[$key]=1
  done < "$ENV_FILE"
else
  (set -o noclobber; printf '# FastToWin R2 setup v1\n' > "$ENV_FILE") || fail 'Cannot create private output file.'
  R2_SETUP_VALIDATED_FILE=yes
  protect_output
fi

banner 'FastToWin: private R2 setup (human-operated)'

stage 'Create and verify a Cloudflare account'
open_url 'https://dash.cloudflare.com/sign-up'
step 'Enter Email and Password in Cloudflare, then Create Account. Never paste login credentials here.'
step 'Open the verification email, follow its link, and sign in.'
step 'My Profile → Email Address must show (verified); Send verification email if needed.'
note 'No domain is needed for this private S3 phase.'
confirm 'Email verified and the intended Cloudflare account selected?' || fail 'Account verification pending.'

stage 'Activate R2 subscription and review billing'
open_url 'https://dash.cloudflare.com/'
say 'Standard free inclusion is shared across the account: 10 GB-month, 1M Class A and 10M Class B per month.'
warn 'Above that allowance, R2 is pay-as-you-go. Two buckets do not double the free inclusion.'
warn 'Budget alerts send email; they do not cap spending or stop usage. Railway proxy usage/egress still applies.'
confirm 'Proceed to R2 checkout with usage billing understood?' || fail 'R2 checkout not authorized.'
step 'Storage & databases → R2 → Overview → complete checkout for the R2 subscription.'
step 'Read the current checkout screen; the final button label varies. Enter billing only in Cloudflare.'
note 'If needed: Billing → Subscriptions → Payment methods → Add Payment Method; complete verification in browser.'
confirm 'R2 subscription active?' || fail 'R2 activation pending.'
if confirm 'Set an optional account budget email alert now?'; then
  step 'Manage Account → Billing → Billable Usage → Create budget alert.'
  step 'Enter Alert name, optional Description, Budget threshold (USD), Email recipients → Save.'
  pause 'Continue after saving the alert.'
else
  note 'Budget alert skipped by choice; usage billing remains active.'
fi

stage 'Create separate private Standard buckets'
open_url 'https://dash.cloudflare.com/'
step 'R2 → Create bucket. Create staging, then production, using different names.'
step 'Use default jurisdiction, automatic location (Automatic/None), default storage class Standard → Create bucket.'
step 'Keep Public Development URL disabled and no custom domain on both buckets; verify settings before continuing.'
step 'R2 Overview → Account Details: copy Account ID (not a token value).'
ask_valid STAGING_R2_ACCOUNT_ID 'Account ID (32 hex characters):'
PRODUCTION_R2_ACCOUNT_ID="$STAGING_R2_ACCOUNT_ID"
ask_valid STAGING_R2_BUCKET 'Staging bucket name (e.g. fasttowin-avatars-staging):'
while :; do
  ask_valid PRODUCTION_R2_BUCKET 'Production bucket name (e.g. fasttowin-avatars-prod):'
  [[ "$STAGING_R2_BUCKET" != "$PRODUCTION_R2_BUCKET" ]] && break
  warn 'Staging and production must use different buckets.'
done
confirm 'Both buckets are Standard, private, and use the default jurisdiction?' || fail 'Bucket verification pending.'
for key in STAGING_R2_ACCOUNT_ID PRODUCTION_R2_ACCOUNT_ID STAGING_R2_BUCKET PRODUCTION_R2_BUCKET; do persist "$key"; done

stage 'Create bucket-scoped S3 keys for each environment'
open_url 'https://dash.cloudflare.com/'
step 'R2 → Overview → Account Details → API Tokens → Manage.'
step 'For EACH environment: Create Account API token (preferred), or Create User API token.'
step 'Select Object Read & Write → Apply to specific buckets only → select only that environment bucket.'
note 'Do not choose Admin or all buckets. A user token depends on the user retaining account access.'
note 'Expiry is optional; inspect the current R2 control (its exact label is not documented). Schedule rotation if set.'
note 'Secret Access Key appears once. It is not the Cloudflare API token value. Store it in your secret manager too.'
for environment in STAGING PRODUCTION; do
  bucket_key="${environment}_R2_BUCKET"
  say "Prepare the $environment token for bucket ${!bucket_key}."
  step 'Object Read & Write → Apply to specific buckets only → this one bucket.'
  ask_valid "${environment}_R2_TOKEN_NAME" 'Token name (use 1–128 letters/digits/dot/underscore/hyphen for this runbook):'
  ask_valid "${environment}_R2_TOKEN_TYPE" 'Token type: account or user:'
  ask_valid "${environment}_R2_TOKEN_EXPIRY" 'Actual expiry UTC (YYYY-MM-DDTHH:MM:SSZ), or none:'
  confirm "Create/verify this $environment token restricted to its ONE bucket?" || fail 'Token scope confirmation pending.'
  step 'Create the token in Cloudflare, then copy the S3 Access Key ID and Secret Access Key below.'
  while :; do
    ask_valid "${environment}_R2_ACCESS_KEY_ID" 'S3 Access Key ID (hidden):' yes
    [[ "$environment" != PRODUCTION || "$PRODUCTION_R2_ACCESS_KEY_ID" != "$STAGING_R2_ACCESS_KEY_ID" ]] && break
    warn 'Use a distinct token/key pair for each bucket.'
  done
  ask_valid "${environment}_R2_SECRET_ACCESS_KEY" 'S3 Secret Access Key (hidden):' yes
  for suffix in TOKEN_NAME TOKEN_TYPE TOKEN_EXPIRY ACCESS_KEY_ID SECRET_ACCESS_KEY; do persist "${environment}_R2_${suffix}"; done
done

stage 'Review metadata and hand off to staging'
say 'Saved public metadata plus two independent S3 key pairs to the fixed ignored credentials file.'
say 'The summary lists variable names only. Do not cat/source this file, paste it into chat, or attach it to logs.'
say 'Map STAGING_R2_* to FASTTOWIN_AVATAR_R2_* in staging; see docs/avatar-object-storage.md.'
say 'Each *_FILE runtime variable accepts a file with ONE key value, not credentials.env.'
say 'No CI secrets, cloud API calls, deployment or runtime activation were performed by this wizard.'
warn 'Production keys are prepared only. Real staging R2 smoke, migration/cleanup acceptance and device checks remain pending.'
note 'Domain/CDN/public delivery is a later phase. Keep r2.dev disabled; it is unsuitable for production.'
pause 'Review the runbook and arrange authorized staging smoke before enabling FASTTOWIN_AVATAR_STORAGE=r2.'
finish
unset STAGING_R2_ACCESS_KEY_ID STAGING_R2_SECRET_ACCESS_KEY PRODUCTION_R2_ACCESS_KEY_ID PRODUCTION_R2_SECRET_ACCESS_KEY
